	}

	if( this_dies_trigger(player, card, event, RESOLVE_TRIGGER_MANDATORY) ){
		if( instance->targets[11].player > 0 ){
			draw_cards(player, instance->targets[11].player);
		}
	}

	return morph(player, card, event, MANACOST_B(1));
}

